const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;

let HPY = input[idx++], ATKY = input[idx++], DEFY = input[idx++];
let HPM = input[idx++], ATKM = input[idx++], DEFM = input[idx++];
let h = input[idx++], a = input[idx++], d = input[idx++];

function ceilDiv(x, y) {
    return Math.floor((x + y - 1) / y);
}

let INF = Number.MAX_SAFE_INTEGER;
let ans = INF;

// We will iterate over possible final ATK and DEF values for Yang
// ATK from 1 to some upper bound, DEF from 0 to some upper bound
// Upper bounds: since stats and prices <=100, we can safely cap
// ATK and DEF increments up to 200 (enough to cover all cases).
for (let atkY = 1; atkY <= 200; atkY++) {
    let dmgToMonster = Math.max(0, atkY - DEFM);
    if (dmgToMonster === 0) continue; // can't damage monster

    let turnsToKillMonster = ceilDiv(HPM, dmgToMonster);

    for (let defY = 0; defY <= 200; defY++) {
        let dmgToYang = Math.max(0, ATKM - defY);
        let hpNeeded;

        if (dmgToYang === 0) {
            // Yang won't take damage, any positive HP is fine
            hpNeeded = 1;
        } else {
            // Yang must survive (turnsToKillMonster - 1) hits
            hpNeeded = (turnsToKillMonster - 1) * dmgToYang + 1;
        }

        let hpIncrease = Math.max(0, hpNeeded - HPY);
        let atkIncrease = Math.max(0, atkY - ATKY);
        let defIncrease = Math.max(0, defY - DEFY);

        let cost = hpIncrease * h + atkIncrease * a + defIncrease * d;
        if (cost < ans) ans = cost;
    }
}

